const data = $input.first().json || {};
const rows = Array.isArray(data.rows) ? data.rows : [];
if (!rows.length) {
  return [{ json: { phone: '', active: 'FALSE', expires_at: '', _empty: true } }];
}
return rows.map((r) => ({
  json: {
    ...r,
    active: r.active === true || String(r.active ?? '').trim().toUpperCase() === 'TRUE' ? 'TRUE' : 'FALSE'
  }
}));
